# DSPy 의 Predict / ChainOfThought / Module 합성을 흉내 낸다. LM 은 규칙으로 답하는 가짜다.
import re  # 실행: PYTHONIOENCODING=utf-8 (이모지 출력)
def fake_lm(fields, text):                      # 실제로는 여기서 LLM 이 불린다
    out = {}
    if "reasoning" in fields: out["reasoning"] = f"본문에서 날짜·시각을 찾는다: {text[:30]}..."
    m = re.search(r"(\d{1,2}) ?(AM|PM)", text)
    if "start" in fields: out["start"] = (f"{int(m[1]) % 12 + (12 if m[2] == 'PM' else 0):02d}:00" if m else None)
    if "event_name" in fields: out["event_name"] = "meeting" if "meeting" in text else None
    if "emoji" in fields: out["emoji"] = "🦷" if "dentist" in text.lower() else "📅"
    return out
class Predict:
    def __init__(self, outputs): self.outputs = outputs
    def __call__(self, text): return fake_lm(self.outputs, text)
class ChainOfThought(Predict):                   # 출력 맨 앞에 reasoning 칸 하나를 더할 뿐
    def __init__(self, outputs): super().__init__(["reasoning"] + outputs)
calendar = []
class UpdateCalendarFromEmail:
    def __init__(self):
        self.extract = ChainOfThought(["event_name", "start"])   # LM 호출 1
        self.pick_emoji = Predict(["emoji"])                     # LM 호출 2
    def forward(self, email):
        d = self.extract(email)
        if d["event_name"] is None or d["start"] is None:        # 평범한 파이썬 제어 흐름
            return {"event": None, "status": "no event found in email"}
        ev = {**d, "emoji": self.pick_emoji(d["event_name"])["emoji"], "minutes": 60}
        calendar.append(ev)
        return {"event": ev, "status": "added to calendar"}
m = UpdateCalendarFromEmail()
print(m.forward("We have a meeting scheduled for this Friday at 10 AM PST."))
print(m.forward("Thanks for sending the slides, they look great!"))
print(len(calendar), "event(s) on calendar")

# ReAct 루프(생각 → 행동 → 관찰)를 흉내 낸다. 정책(policy)이 LLM 자리다 — 여기선 각본으로 대신한다.
cal = {"e1": {"title": "CS329Z Lecture", "start": "13:30"}, "e2": {"title": "Coffee with John", "start": "15:00"}}
def list_events():            return {k: v["title"] + " @" + v["start"] for k, v in cal.items()}
def move_event(eid, start):   cal[eid]["start"] = start; return f"{eid} moved to {start}"
TOOLS = {"list_events": list_events, "move_event": move_event}
def policy(history):          # 실제로는 지금까지의 기록 전체를 프롬프트로 LLM 에 넣고 다음 행동을 받는다
    if len(history) == 1: return ("커피 일정이 어느 것인지 먼저 본다", "list_events", {})
    if len(history) == 2: return ("e2 가 커피다. 30분 늦춘다", "move_event", {"eid": "e2", "start": "15:30"})
    return ("끝났다", "finish", {"summary": "Coffee with John 을 15:30 으로 옮겼다"})
def react(request, max_steps=5):
    history = [("request", request)]
    for step in range(1, max_steps + 1):
        thought, tool, args = policy(history)
        if tool == "finish": return args["summary"], history
        obs = TOOLS[tool](**args)                       # 도구 실행 결과 = 관찰
        print(f"[{step}] thought={thought} | act={tool}{args} | obs={obs}")
        history.append((tool, obs))
    return "budget exhausted", history                  # 무한 루프 방지: 최대 단계 수
summary, h = react("Move my coffee with John 30 minutes later")
print("summary:", summary, "| LLM 호출 수:", len(h))

# LangGraph 의 StateGraph 를 흉내 낸 30줄. 노드는 state 를 받아 '바꾼 칸만' dict 로 돌려준다.
START, END = "__start__", "__end__"
class StateGraph:
    def __init__(self): self.nodes, self.edges, self.cond = {}, {}, {}
    def add_node(self, name, fn): self.nodes[name] = fn
    def add_edge(self, a, b): self.edges[a] = b
    def add_conditional_edges(self, a, router): self.cond[a] = router
    def invoke(self, state, max_steps=20):
        cur, state = START, dict(state)
        for _ in range(max_steps):
            nxt = self.cond[cur](state) if cur in self.cond else self.edges[cur]
            print(f"  {cur} -> {nxt}")
            if nxt == END: return state
            state.update(self.nodes[nxt](state))       # 부분 갱신을 공유 state 에 병합
            cur = nxt
        raise RuntimeError("step limit")                # 순환 그래프의 안전장치
def extract(s):   return {"details": {"name": "Dentist", "start": "09:00"} if "dentist" in s["email"].lower() else None}
def pick_emoji(s): return {"emoji": "🦷"}
def add_to_cal(s): return {"status": "added to calendar"}
def route(s):     return "pick_emoji" if s["details"] else END   # 조건 엣지 = 다음 노드 이름을 돌려주는 함수
g = StateGraph()
for n, f in [("extract", extract), ("pick_emoji", pick_emoji), ("add_to_calendar", add_to_cal)]: g.add_node(n, f)
g.add_edge(START, "extract"); g.add_conditional_edges("extract", route)
g.add_edge("pick_emoji", "add_to_calendar"); g.add_edge("add_to_calendar", END)
for mail in ["Dentist appointment confirmed Oct 7 at 9 AM", "Your OpenRouter credits have arrived!"]:
    print(mail); print("  =>", g.invoke({"email": mail}))

# Temporal 의 '활동(activity) 재시도 + 실행 이력' 을 흉내 낸다. 실제 Temporal 은 이력을 서버에 저장해 재시작 후에도 이어 간다.
import random
random.seed(3)
history = []                                         # 서버가 들고 있는 이벤트 이력 역할
def activity(name, fn, max_attempts=5, backoff=1.0):
    for attempt in range(1, max_attempts + 1):
        try:
            out = fn(); history.append((name, attempt, "completed", out)); return out
        except Exception as e:
            history.append((name, attempt, "failed", str(e)))
            backoff *= 2                             # 지수 백오프(여기선 기다리지 않고 값만 기록)
    raise RuntimeError(f"{name} gave up after {max_attempts}")
def flaky_pick_emoji():
    if random.random() < 0.6: raise TimeoutError("emoji LLM timeout")
    return "🦷"
def workflow(email):                                 # 워크플로 = 활동들을 잇는 결정론적 코드
    d = activity("extract_event", lambda: {"title": "Dentist", "start": "09:00"})
    e = activity("pick_emoji", flaky_pick_emoji)
    return activity("add_to_calendar", lambda: f"added {e} {d['title']}")
print(workflow("Dentist appointment confirmed"))
for row in history: print(row)
